function(container, apiUrl, tables) {
  let selectedProducts = [];
  let orderItems = [];

  // 店舗データ、商品データ、需要予測データ、発注データのテーブルインデックス
  const storeTableIndex = 1;
  const productTableIndex = 2;
  const demandTableIndex = 9;
  const orderTableIndex = 10;

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#order-date').value = today;

  // 店舗選択肢を描画
  function renderStoreOptions(stores) {
    const storeSelect = container.querySelector('#store-select');
    storeSelect.innerHTML = '<option value="">店舗を選択してください</option>';
    stores.forEach(store => {
      if (store.有効フラグ) {
        storeSelect.innerHTML += `<option value="${store.店舗ID}">${store.店舗名}</option>`;
      }
    });
  }

  // 商品一覧を描画
  function renderProductList(products) {
    const tbody = container.querySelector('#product-list');
    tbody.innerHTML = products.map(product => {
      const prediction = getDemandPrediction(product.商品ID);
      return `
        <tr data-id="${product.商品ID}">
          <td><input type="checkbox" class="product-checkbox" data-id="${product.商品ID}"></td>
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>${product.単価 || 0}円</td>
          <td>${prediction ? prediction.予測数量 : 0}</td>
          <td><input type="number" class="input manual-quantity" data-id="${product.商品ID}" min="0" value="${prediction ? prediction.予測数量 : 0}"></td>
          <td><button class="action-btn secondary prediction-btn" data-id="${product.商品ID}">予測根拠</button></td>
          <td><button class="action-btn add-to-order" data-id="${product.商品ID}">発注リストに追加</button></td>
        </tr>
      `;
    }).join('');
  }

  // 発注リストを描画
  function renderOrderList() {
    const tbody = container.querySelector('#order-list');
    tbody.innerHTML = orderItems.map(item => `
      <tr data-id="${item.商品ID}">
        <td>${item.商品コード}</td>
        <td>${item.商品名}</td>
        <td>${item.単価}円</td>
        <td><input type="number" class="input order-quantity" data-id="${item.商品ID}" min="1" value="${item.発注数量}"></td>
        <td class="subtotal">${(item.単価 * item.発注数量).toLocaleString()}円</td>
        <td><button class="action-btn secondary remove-from-order" data-id="${item.商品ID}">削除</button></td>
      </tr>
    `).join('');
    calculateTotal();
  }

  // 需要予測データを取得
  function getDemandPrediction(productId) {
    const storeId = container.querySelector('#store-select').value;
    if (!storeId) return null;

    const predictions = tables[demandTableIndex]?.records || [];
    return predictions.find(p => p.商品ID === productId && p.店舗ID === storeId);
  }

  // 発注総額を計算
  function calculateTotal() {
    const total = orderItems.reduce((sum, item) => sum + (item.単価 * item.発注数量), 0);
    container.querySelector('#total-amount').textContent = total.toLocaleString();
  }

  // バリデーション
  function validateForm() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const deliveryDate = container.querySelector('#delivery-date').value;

    if (!storeId) {
      alert('店舗を選択してください');
      return false;
    }

    if (!orderDate) {
      alert('発注日付を入力してください');
      return false;
    }

    if (!deliveryDate) {
      alert('納期を指定してください');
      return false;
    }

    if (new Date(deliveryDate) < new Date(orderDate)) {
      alert('納期は発注日より後の日付を指定してください');
      return false;
    }

    if (orderItems.length === 0) {
      alert('発注する商品を選択してください');
      return false;
    }

    // 発注数量のバリデーション
    for (const item of orderItems) {
      if (!item.発注数量 || item.発注数量 <= 0) {
        alert('発注数量は1以上で入力してください');
        return false;
      }
    }

    return true;
  }

  // 初期データ読み込み
  Promise.all([
    window.aivicApi.list(storeTableIndex),
    window.aivicApi.list(productTableIndex)
  ]).then(([stores, products]) => {
    if (stores) renderStoreOptions(stores);
    if (products) renderProductList(products.filter(p => p.有効フラグ));
  });

  // 商品検索
  container.querySelector('#btn-search-product').addEventListener('click', async () => {
    const keyword = container.querySelector('#product-search').value;
    const categoryId = container.querySelector('#category-select').value;

    const products = await window.aivicApi.list(productTableIndex);
    if (!products) return;

    let filteredProducts = products.filter(p => p.有効フラグ);

    if (keyword) {
      filteredProducts = filteredProducts.filter(p => 
        (p.商品名 && p.商品名.includes(keyword)) || 
        (p.商品コード && p.商品コード.includes(keyword))
      );
    }

    if (categoryId) {
      filteredProducts = filteredProducts.filter(p => p.商品カテゴリID === categoryId);
    }

    renderProductList(filteredProducts);
  });

  // 在庫状況確認
  container.querySelector('#btn-stock-check').addEventListener('click', () => {
    const storeId = container.querySelector('#store-select').value;
    if (!storeId) {
      alert('店舗を選択してください');
      return;
    }

    const modal = container.querySelector('#stock-modal');
    const details = container.querySelector('#stock-details');

    details.innerHTML = `
      <div class="table-wrap">
        <table>
          <thead>
            <tr>
              <th>商品名</th>
              <th>現在庫数</th>
              <th>安全在庫数</th>
              <th>リードタイム</th>
              <th>推奨発注数量</th>
            </tr>
          </thead>
          <tbody>
            <tr>
              <td>サンプル商品A</td>
              <td>50</td>
              <td>20</td>
              <td>3日</td>
              <td>30</td>
            </tr>
            <tr>
              <td>サンプル商品B</td>
              <td>15</td>
              <td>25</td>
              <td>5日</td>
              <td>40</td>
            </tr>
          </tbody>
        </table>
      </div>
    `;

    modal.classList.remove('hidden');
  });

  // 過去実績参照
  container.querySelector('#btn-history-check').addEventListener('click', () => {
    const storeId = container.querySelector('#store-select').value;
    if (!storeId) {
      alert('店舗を選択してください');
      return;
    }

    const modal = container.querySelector('#history-modal');
    const details = container.querySelector('#history-details');

    details.innerHTML = `
      <div class="table-wrap">
        <table>
          <thead>
            <tr>
              <th>商品名</th>
              <th>先月発注量</th>
              <th>先月売上量</th>
              <th>2ヶ月前発注量</th>
              <th>2ヶ月前売上量</th>
              <th>3ヶ月前発注量</th>
              <th>3ヶ月前売上量</th>
            </tr>
          </thead>
          <tbody>
            <tr>
              <td>サンプル商品A</td>
              <td>100</td>
              <td>95</td>
              <td>120</td>
              <td>118</td>
              <td>90</td>
              <td>88</td>
            </tr>
            <tr>
              <td>サンプル商品B</td>
              <td>80</td>
              <td>75</td>
              <td>85</td>
              <td>82</td>
              <td>70</td>
              <td>68</td>
            </tr>
          </tbody>
        </table>
      </div>
    `;

    modal.classList.remove('hidden');
  });

  // 発注総額表示
  container.querySelector('#btn-calculate-total').addEventListener('click', () => {
    calculateTotal();
  });

  // 発注書作成
  container.querySelector('#btn-create-order').addEventListener('click', async () => {
    if (!validateForm()) return;

    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;
    const deliveryDate = container.querySelector('#delivery-date').value;

    try {
      // 各商品の発注データを保存
      for (const item of orderItems) {
        const orderData = {
          店舗ID: storeId,
          商品ID: item.商品ID,
          発注日: new Date(orderDate).toISOString(),
          納期予定日: new Date(deliveryDate).toISOString(),
          発注数量: item.発注数量,
          発注単価: item.単価,
          発注金額: item.単価 * item.発注数量,
          発注方法: 'AI推奨採用',
          発注ステータス: '発注済',
          自動発注フラグ: false,
          作成者ID: 'current-user-id',
          更新者ID: 'current-user-id'
        };

        await window.aivicApi.save(orderTableIndex, orderData);
      }

      alert('発注書が正常に作成されました');

      // フォームをリセット
      orderItems = [];
      renderOrderList();
      container.querySelector('#store-select').value = '';
      container.querySelector('#order-date').value = today;
      container.querySelector('#delivery-date').value = '';

      // 発注管理画面に遷移
      window.showScreen('scr-1778591852463');

    } catch (error) {
      alert('発注書の作成に失敗しました');
    }
  });

  // イベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 発注リストに追加
    const addBtn = e.target.closest('.add-to-order');
    if (addBtn) {
      const productId = addBtn.dataset.id;
      const products = await window.aivicApi.list(productTableIndex);
      const product = products?.find(p => p.商品ID === productId);
      if (!product) return;

      const manualQuantity = container.querySelector(`.manual-quantity[data-id="${productId}"]`).value;
      const quantity = parseInt(manualQuantity) || 1;

      if (quantity <= 0) {
        alert('発注数量は1以上で入力してください');
        return;
      }

      // 既に追加済みかチェック
      const existingIndex = orderItems.findIndex(item => item.商品ID === productId);
      if (existingIndex >= 0) {
        orderItems[existingIndex].発注数量 = quantity;
      } else {
        orderItems.push({
          商品ID: productId,
          商品コード: product.商品コード,
          商品名: product.商品名,
          単価: product.単価,
          発注数量: quantity
        });
      }

      renderOrderList();
    }

    // 発注リストから削除
    const removeBtn = e.target.closest('.remove-from-order');
    if (removeBtn) {
      const productId = removeBtn.dataset.id;
      orderItems = orderItems.filter(item => item.商品ID !== productId);
      renderOrderList();
    }

    // 予測根拠表示
    const predictionBtn = e.target.closest('.prediction-btn');
    if (predictionBtn) {
      const productId = predictionBtn.dataset.id;
      const prediction = getDemandPrediction(productId);

      const modal = container.querySelector('#prediction-modal');
      const details = container.querySelector('#prediction-details');

      details.innerHTML = `
        <div style="margin-bottom: 1rem;">
          <h4>予測数量: ${prediction ? prediction.予測数量 : 0}個</h4>
          <p>予測精度: ${prediction ? prediction.予測精度 : 0}%</p>
        </div>
        <div style="margin-bottom: 1rem;">
          <h5>予測根拠データ:</h5>
          <ul>
            <li>過去3ヶ月の平均売上: 85個/月</li>
            <li>季節要因補正: +15%</li>
            <li>曜日要因補正: +5%</li>
            <li>天候要因補正: -3%</li>
            <li>イベント要因補正: +10%</li>
          </ul>
        </div>
        <div>
          <h5>信頼度情報:</h5>
          <p>この予測は過去のデータパターンに基づいており、${prediction ? prediction.予測精度 : 0}%の精度で算出されています。</p>
        </div>
      `;

      modal.classList.remove('hidden');
    }

    // モーダルを閉じる
    if (e.target.closest('#btn-close-modal')) {
      container.querySelector('#prediction-modal').classList.add('hidden');
    }

    if (e.target.closest('#btn-close-stock-modal')) {
      container.querySelector('#stock-modal').classList.add('hidden');
    }

    if (e.target.closest('#btn-close-history-modal')) {
      container.querySelector('#history-modal').classList.add('hidden');
    }
  });

  // 発注数量変更時の処理
  container.addEventListener('input', (e) => {
    if (e.target.classList.contains('order-quantity')) {
      const productId = e.target.dataset.id;
      const quantity = parseInt(e.target.value) || 0;

      const item = orderItems.find(item => item.商品ID === productId);
      if (item) {
        item.発注数量 = quantity;
        // 小計を更新
        const row = e.target.closest('tr');
        const subtotalCell = row.querySelector('.subtotal');
        subtotalCell.textContent = (item.単価 * quantity).toLocaleString() + '円';
        calculateTotal();
      }
    }
  });
}
